Statistic Characters of Perlin Noise

vs = sort(flat_matrix$value)
m = mean(vs)
sd = sd(vs)
rd = rnorm(length(vs), m,sd)

tibble(
  rank = 1:length(vs),
  perline_noise = vs,
  normal = rd |&gt; sort()
) |&gt; 
  ggplot() + 
  geom_density(aes(x = perline_noise),color="blue",linewidth=1) + 
