vis_top_score.ufo_mart = function(x, 
    variable,top_n,desc=TRUE, 
    label_from = "full_name", 
    colorpalette = "brewer.bu_pu", 
    text_size=0.7,
    limits=c()
) {
    variable = enquo(variable)
    var_label = as_label(variable)
    if (length(limits) == 0) {
        limits = pull(x, {{variable}}) |&gt; range()
    }
    x=x |&gt; 
        arrange({{variable}} |&gt; desc())
    if (desc) {
        x = x |&gt; slice_head(n=top_n)
    } else {
        x = x |&gt; slice_tail(n=top_n)
    }
    mid_point = pull(x, {{variable}}) |&gt; median()
    label_glue = glue::glue("{{{label_from}}}")
    x |&gt; 
        # transform
        mutate(
            "{var_label}" := round(!!variable,2),
            text_color=ifelse({{variable}} &gt; mid_point, "white", "black"),
            label = glue::glue(label_glue)
        ) |&gt; 
        sf::st_as_sf() |&gt; 
        tmap::tm_shape() +
        tmap::tm_polygons(
            fill=var_label,
            fill.scale = tmap::tm_scale_continuous_log(values=colorpalette),
            fill.legend = tmap::tm_legend_hide(),
            fill_alpha=0.5,
            limits=limits
        ) +
        tmap::tm_text(
            text="label",
            col="text_color",
            size=text_size
        )
}




Function wraper for spdep local moran
# Local Moran Statistics -----------------------
local_moran_c = function(variable, nb, get = c("Ii","E.Ii","Var.Ii","Pr(z &gt; E(Ii))")) {
    lw = spdep::nb2listw(nb, style="W",zero.policy = TRUE)
    t = spdep::localmoran_perm( {{variable}}, lw, alternative="greater")
    t[,get]
}
local_moran_c_quadr= function(variable, nb, get = c("Ii","E.Ii","Var.Ii","Pr(z &gt; E(Ii))")) {
    lw = spdep::nb2listw(nb, style="W",zero.policy = TRUE)
    t = spdep::localmoran_perm( {{variable}}, lw, alternative="greater")
    attributes(t)$quadr$mean
}



